const crypto = require('crypto');
const SEED = '2026-Q3-winback';
const HOLDOUT = 0.15;
return $input.all().map(item => {
  const id = String(item.json.entity_id);
  const h = crypto.createHash('sha256').update(`${SEED}:${id}`).digest();
  const treated = h.readBigUInt64BE(0) / 2n ** 64n >= HOLDOUT;
  return { json: { ...item.json, treated } };
});
